class CalibratedJoinSink {
  Map<String, Calibration> cache;
  void onCalibration(Calibration c){ cache.put(c.sensorId, c); }
  void onReading(Reading r){
    Calibration c = cache.get(r.sensorId);
    r.factor = (c != null) ? c.factor : 1.0;
    emit(r);
    // optionally track buffered items for late calibration
  }
}
